package com.nimbusbill.customer.service;
import com.nimbusbill.customer.entity.*; import com.nimbusbill.customer.exception.ResourceNotFoundException; import com.nimbusbill.customer.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class InvoiceDocumentService {
 private final InvoiceRepository invoices; private final InvoiceLineItemRepository lines; public InvoiceDocumentService(InvoiceRepository i,InvoiceLineItemRepository l){invoices=i;lines=l;}
 @Transactional(readOnly=true) public byte[] pdf(UUID id){Invoice i=invoices.findById(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found: "+id));List<String> text=new ArrayList<>();text.add("NimbusBill Invoice");text.add("Invoice: "+i.getInvoiceNumber());text.add("Status: "+i.getStatus());text.add("Invoice date: "+i.getInvoiceDate()+"   Due: "+i.getDueDate());text.add("Customer: "+i.getCustomer().getCustomerName());text.add("Billing account: "+i.getBillingAccount().getAccountName());text.add("");text.add("Product                 Base          Tax          Total");for(InvoiceLineItem l:lines.findByInvoiceIdOrderByProductCode(id))text.add(l.getProductCode()+"    "+l.getBaseAmount()+"    "+l.getTaxAmount()+"    "+l.getTotalAmount());text.add("");text.add("Subtotal: "+i.getCurrency()+" "+i.getSubtotal());text.add("Tax: "+i.getTaxTotal());text.add("Adjustments: "+i.getAdjustmentTotal());text.add("Grand total: "+i.getCurrency()+" "+i.getGrandTotal());return render(text);}
 private byte[] render(List<String> lines){StringBuilder stream=new StringBuilder("BT /F1 18 Tf 50 790 Td ");boolean first=true;for(String line:lines){if(!first)stream.append("0 -22 Td ");first=false;stream.append("(").append(line.replace("\\","\\\\").replace("(","\\(").replace(")","\\)")).append(") Tj ");}stream.append("ET");String[] objects={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>","<< /Length "+stream.length()+" >>\nstream\n"+stream+"\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};try{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write("%PDF-1.4\n".getBytes(StandardCharsets.US_ASCII));List<Integer> offsets=new ArrayList<>();for(int n=0;n<objects.length;n++){offsets.add(out.size());out.write(((n+1)+" 0 obj\n"+objects[n]+"\nendobj\n").getBytes(StandardCharsets.US_ASCII));}int xref=out.size();out.write(("xref\n0 "+(objects.length+1)+"\n0000000000 65535 f \n").getBytes(StandardCharsets.US_ASCII));for(int offset:offsets)out.write(String.format("%010d 00000 n \n",offset).getBytes(StandardCharsets.US_ASCII));out.write(("trailer << /Size "+(objects.length+1)+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF").getBytes(StandardCharsets.US_ASCII));return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
}
